/**
 * NSE equity trading-symbol -> official listed company name, sourced from
 * Zerodha Kite Connect's public instrument master
 * (https://api.kite.trade/instruments, downloaded 2026-09-20, filtered to
 * exchange=NSE, segment=NSE, instrument_type=EQ) — a real broker's
 * authoritative reference, not a guess. Refreshed periodically as NSE lists/
 * delists securities; current as of the download date above.
 *
 * Exists to bridge Angel One's "Trades and Charges" CSV export, which names
 * equity rows by full company display name (e.g. "CANARA BANK", "IDFC FIRST
 * BANK LIMITED"), against its live SmartAPI holdings/trades endpoints, which
 * return the bare NSE trading symbol (e.g. "CANBK", "IDFCFIRSTB"). Many NSE
 * tickers are abbreviations with no textual relationship to the company name
 * (CANBK/Canara Bank, TCS/Tata Consultancy Services, INFY/Infosys, M&M/
 * Mahindra & Mahindra, PFC/Power Finance Corp) that no prefix/suffix
 * heuristic can bridge — see matchEquityInstrumentByName in
 * instrument.service.ts, which uses this table as a name-to-name bridge
 * rather than comparing the raw ticker against the CSV string directly.
 */
